<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin — Fieldcraft</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600&display=swap" rel="stylesheet"><style>:root{--ink:#07110d;--lime:#caff39;--line:#e0e7de;--muted:#718078}*{box-sizing:border-box}body{margin:0;background:#f6f8f4;color:var(--ink);font:500 13px Manrope,sans-serif}.side{position:fixed;inset:0 auto 0 0;width:244px;padding:26px 15px;background:var(--ink);color:white;display:flex;flex-direction:column}.brand{color:white;text-decoration:none;font:600 26px Oswald,sans-serif;margin:4px 10px 43px}.brand i{display:inline-block;width:20px;height:20px;margin-right:8px;background:var(--lime);border-radius:2px 11px 2px 11px;transform:rotate(-20deg)}.nav a{display:flex;gap:11px;align-items:center;padding:11px 10px;margin:2px 0;border-radius:5px;text-decoration:none;color:#b9c5ba;font-size:12px;font-weight:700}.nav a:hover,.nav a.active{background:#23382c;color:white}.nav a.active span{color:var(--lime)}.logout{margin-top:auto}.logout button{width:100%;border:0;background:#1a2c21;color:#c5d0c5;padding:10px;border-radius:4px;font-size:11px;cursor:pointer}.main{margin-left:244px;padding:33px 39px;max-width:1600px}.crumb{font:500 10px 'DM Mono';letter-spacing:.1em;color:var(--muted)}h1{margin:8px 0 26px;font:600 40px/.95 Oswald,sans-serif;text-transform:uppercase}.topline{display:flex;align-items:center;justify-content:space-between;gap:15px}.btn{border:0;border-radius:4px;padding:11px 14px;background:var(--ink);color:white;font-size:11px;font-weight:800;text-decoration:none;cursor:pointer}.btn.lime{background:var(--lime);color:var(--ink)}.panel{background:#fff;border:1px solid var(--line);border-radius:8px;padding:19px}.notice{margin:0 0 18px;background:#e7f4da;color:#416f2c;padding:11px 13px;border-radius:5px;font-size:11px}.table{width:100%;border-collapse:collapse}.table th{text-align:left;color:var(--muted);font:500 9px 'DM Mono';letter-spacing:.08em;padding:8px;border-bottom:1px solid var(--line)}.table td{padding:12px 8px;border-bottom:1px solid #f0f3ef;font-size:11px}.status{padding:4px 6px;border-radius:3px;background:#eaf4df;color:#39752a;font:500 9px 'DM Mono'}.thumb{width:48px;height:48px;object-fit:cover;background:#edf2eb;border-radius:5px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.form{max-width:900px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field label{display:block;font-size:10px;font-weight:800;margin:0 0 6px}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);border-radius:4px;background:white;padding:10px;outline:0}.field textarea{min-height:100px}.full{grid-column:1/-1}.variants{margin-top:20px}.variant-row{display:grid;grid-template-columns:1.35fr 1fr .6fr 1fr .7fr;gap:8px;margin-top:8px}.muted{color:var(--muted)}.actions{display:flex;gap:7px}.danger{background:#fff0ec;color:#bc371a}.small{padding:7px 9px;font-size:10px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.stat h2{margin:8px 0 0;font:600 30px Oswald,sans-serif}.stat small{color:var(--muted);font-size:10px}@media(max-width:800px){.side{width:58px;padding:20px 8px}.brand{font-size:0;margin:6px 12px 38px}.brand i{width:24px;height:24px;margin:0}.nav b,.logout{display:none}.nav a{justify-content:center}.main{margin-left:58px;padding:24px 15px}.form-grid{grid-template-columns:1fr}.variant-row{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr}.hide-sm{display:none}} </style></head><body><aside class="side"><a class="brand" href="{{ route('admin.dashboard') }}"><i></i>FIELDCRAFT</a><nav class="nav"><a class="{{ request()->routeIs('admin.dashboard')?'active':'' }}" href="{{ route('admin.dashboard') }}"><span>▦</span><b>Tổng quan</b></a><a class="{{ request()->routeIs('admin.products.*')?'active':'' }}" href="{{ route('admin.products.index') }}"><span>◇</span><b>Sản phẩm</b></a><a class="{{ request()->routeIs('admin.orders.*')?'active':'' }}" href="{{ route('admin.orders.index') }}"><span>□</span><b>Đơn hàng</b></a><a class="{{ request()->routeIs('admin.coupons.*')?'active':'' }}" href="{{ route('admin.coupons.index') }}"><span>%</span><b>Mã giảm giá</b></a><a href="{{ route('store.home') }}"><span>↗</span><b>Xem cửa hàng</b></a></nav><form class="logout" method="POST" action="{{ route('logout') }}">@csrf<button>ĐĂNG XUẤT</button></form></aside><main class="main">@if(session('success'))<div class="notice">✓ {{ session('success') }}</div>@endif @yield('content')</main></body></html>
